import React, { useEffect, memo, useRef } from "react";

import {  updStore,  parseDate, qryKClient, offset, isValidFunction, getStore } from "../../../stores/Utils";


import { NavLink } from "react-router-dom";
import { SvgIcon_Cmpt } from "../../../components";
	
const Svg = SvgIcon_Cmpt();


const ClientItem  = ({ data, show, range2Scroll, updRange, type }) => {



	
	const itemRef = useRef(null);
	const scrollRef = useRef(0);
	const inViewPort = useRef(false);
	const refInt = useRef(null);

	
	useEffect(() => {
		if(range2Scroll){
			refInt.current = 
			setInterval(() => {
				let scrollTop = window.pageYOffset || document.documentElement.scrollTop;
				if(!inViewPort.current && scrollRef.current !== scrollTop){
					scrollRef.current = scrollTop;
					let dmz = offset(itemRef.current);
					if(dmz.top + dmz.height - scrollRef.current < 0){
						if(isValidFunction(updRange)){
							inViewPort.current = true;
							updRange();
						}
					}
				}
			}, 250); 
		}
		return () => {
			refInt.current && clearInterval(refInt.current);
		}
	}, [range2Scroll]);

	
	if(!show){
		return null;
	}
	


	// const data = getStore("client_list_"+type)?.[elmId];
	


	const update = async () => {
		window.scrollTo(0,0);
		updStore(qryKClient(),data);
	}

	let amount = data?.amount ? (data?.amount*1).toFixed(2) : "0.00";

	let categoryLabel = getStore("categories_ids")?.[data?.categoryId]?.name;
	

	return (
		<NavLink className=""  
			ref={itemRef}
			to={{
				"pathname": "/movements/detail" ,
				"search": "?cId="+ data?.movementId + "&view=1"
			}}
		>
			<div className="client_item_box gWXAaj jlytmu" onClick={update}  style={{marginBottom: 9}}>
				<div className="_dsplFlx">
					<div className="">
						<div className="name  title  _dsplFlx " >



						{data?.categoryId? null: 
						<div className="icon_action">
							<Svg name={"help"} color={"var(--partial-success)"} size={18}	/>
						</div>
						
						}
						{`${data?.title}`}
						</div>
						<div className="name  date " >
							{`${parseDate(data?.date*1)}`}
						</div>
						<div className="category _dsplFlx" >
							{data?.imagePath? 
							<div className="icon_action" style={{padding: "3px 4px 0 0"}}>
								<Svg name={"image_outline"} color={"#F7251A"} size={14}	/>
							</div>
							:null}
							{categoryLabel}
						</div>
					</div>
					
					<div className="flexSpace"/>
					<div className="name amount lbl_tx">
						${amount}
					</div>
				</div>
			</div>
		</NavLink>
	)
}


const customComparator = (prevProps, nextProps) => {
	let ignoreMemo = getStore("ignoreMemo") || {};
	if(ignoreMemo?.[nextProps.elmId]){
		ignoreMemo[nextProps.elmId] -=1;
		if(!ignoreMemo?.[nextProps.elmId]){
			delete ignoreMemo?.[nextProps.elmId];
		}
		updStore("ignoreMemo", ignoreMemo);
		// console.log("ignoreMemo", ignoreMemo, nextProps.elmId)
		return false;
	}
	// console.log("customComparator", nextProps.elmId , prevProps.elmId)
	return nextProps.elmId === prevProps.elmId  && nextProps.show === prevProps.show  && nextProps.range2Scroll === prevProps.range2Scroll; 
};

export default memo(ClientItem, customComparator);

