const Provider2Filter  = ({ data,  confirm }) => {
	
	

	const frmNm = "range"

	const [initialize, setInitialize] = useState(false);

	const [obs, set_obs] = useState(1);
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	const getallCategoriesMobile =  () => {
		getall_provider(updObs);
	}
	
	useEffect(() => {
		if (!initialize) {
			
			setInitialize(true);
			set_obs(gen16CodeId());
			getallCategoriesMobile()
		}
	});

	const updCategoryFilter = ( v) => {
		updStore("provider_filter",v);
		set_obs(gen16CodeId());
			if(isValidFunction(confirm)){
				close();
				confirm();
			}
		
	};





	const close  = ()  => {
		data?.modalID && CloseModal({id:data?.modalID});
	}

	let data2Render = getStore("providers_list");

	return(
		<div style={{
			height: "80vh",
			width: "80vw",
			overflow: "auto",
			background: "var(--dark-800)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title blue30">
					Clientes
				</p>
				<div className="flexSpace"/>
			
			</div>
			
			
			
			<div className=" spaceAround flxWrp scollVh" style={{marginTop:20, maxHeight: "calc( 78vh - 70px)"}}>
				
				{data2Render && ObjectKeys(data2Render)?.map(cid=>{
					return (
						<BtnCategory
							data={data2Render[cid]}
							elmId={data2Render[cid].providerId} 
							label={data2Render[cid].name} 
							clickHandler={updCategoryFilter}
							active={getStore("provider_filter")}
							key={data2Render[cid].providerId}
						/>
					)
				})}
			</div>
		
			
		</div>
	)

}



export default Provider2Filter;








const BtnCategory  = ({ clickHandler, label, active,  elmId}) => {
	let nexV = active === elmId?null:elmId;
	return (
		<div className={` btn_filter y2 itmMrg ${active === elmId?"active":""} `} onClick={()=>clickHandler(nexV)} >
			<span className={"y2"}>
				{label}
			</span>
		</div>
	)
}



