const RangeDate  = ({ data,  confirm }) => {
	
	

	const frmNm = "range"

	const [initialize, setInitialize] = useState(false);

	const [obs, set_obs] = useState(1);
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}


	
	useEffect(() => {
		if (!initialize) {
			
			setInitialize(true);
			set_obs(gen16CodeId());
			
		}
	});

	const updFrm = (f, v) => {
		let frm2 = getStore(frmNm) || {};
		frm2[f] = v;
		updStore(frmNm, frm2);
		set_obs(gen16CodeId())
	};


	const updYU =  (v) => {
		let now = (new Date())
		
	
		
	
		
		if(v==="last1M"){
			let mnth = now.getMonth() +1;
			let dt = (new Date((now.getMonth()+1)+"/01/"+now.getFullYear()));
			let initDateMP = dt.getTime();
			let lastDateMP = dt.setMonth(mnth) - 600;
			updStore("date_range_comps", {initDate: initDateMP, lastDate: lastDateMP} );
		}
		else if(v==="last3M"){
			let mnth = now.getMonth() +1;
			let initM = now.getMonth() -3;
			if(initM<0){
				initM = 0;
			}
			let dt = (new Date((now.getMonth()+1)+"/01/"+now.getFullYear()));
			let initDateMP = dt.setMonth(initM);
			let lastDateMP = dt.setMonth(mnth) - 600;
			updStore("date_range_comps", {initDate: initDateMP, lastDate: lastDateMP} );
		}
		else if(v==="last6M"){
			let mnth = now.getMonth() +1;
			let initM = now.getMonth() -6;
			if(initM<0){
				initM = 0;
			}
			let dt = (new Date((now.getMonth()-6)+"/01/"+now.getFullYear()));
			let initDateMP = dt.setMonth(initM);
			let lastDateMP = dt.setMonth(mnth) - 600;
			updStore("date_range_comps", {initDate: initDateMP, lastDate: lastDateMP} );
		}
		else if(v==="allYear"){
			let YY = now.getFullYear()*1;
			let YY2 = now.getFullYear()*1+1;
			let initDate = (new Date("01/01/"+YY)).getTime(); 
			let lastDate = (new Date("01/01/"+YY2)).getTime() - 10;
			updStore("date_range_comps", {initDate: initDate, lastDate: lastDate} );
		}
		//updStore("date_range_submayor", {initDate: initDateMP, lastDate: lastDateMP} );
		updStore("date_range_option",v)
		set_obs(gen16CodeId());
		if(isValidFunction(confirm)){
			close();
			confirm();
		}
	}


	const confirmCalendar = (v) => {
        let nv = {...v};
		nv.initDate = nv.initDate -100;
		nv.lastDate = nv.lastDate + 86380000;
		updStore("date_range_comps",nv);
		if(isValidFunction(confirm)){
			close();
			confirm();
		}
	}
	
	const openCal =  (v) => {
		updStore("date_range_option",v)
		set_obs(gen16CodeId());
		let modal_data = {};
		modal_data["zIndex"] = 950;
		modal_data["height"] = "80vh";
		// data['observeResize']=true;
		modal_data["props"] = { minHeight: "1vh", overlay: true };
		modal_data["content"] = 
			<CalendarModalPicker 
				onConfirm={confirmCalendar} 
				isRange={true}
				colors={{
					"--calendar-primary-color":"var(--primary-blue--backg-30)",
					"--calendar-primary-backcolor":"var(--primary-blue--hover-back-30)",
					"--calendar-selected_lbl_color":"var(--primary-blue--color-30)",
					
					"--calendar-light-backcolor":"var(--dark-800)",
					"--calendar-primary-hover-backcolor":"var(--hrm_palette-blue-purple_100)",

					"--calendar-light-300":"var(--light-300)",
					"--calendar-light-200":"var(--light-200)",
					"--calendar-light-100":"var(--light-100)",
					"--calendar-dark-800":"var(dark-800)",
					"--calendar-white-100":"var(--primary-blue--color-30)",
					"--calendar-white":"var(--white)",
					
					  
				}}
			/>
		
		OpenModal(modal_data);
		
	}

	const close  = ()  => {
		data?.modalID && CloseModal({id:data?.modalID});
	}

	return(
		<div style={{
			height: "300px",
			width: "80vw",
			overflow: "auto",
			background: "var(--dark-800)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title blue30">
					{getFNMLabels(55)}
				</p>
				<div className="flexSpace"/>
			
			</div>
			
			
			
			<div className="_dsplFlx spaceAround" style={{marginTop:20}}>
				
			</div>
		
			<RadioBox label={getFNMLabels(60)} active={getStore("date_range_option") === "last1M" } updSelect={()=>updYU("last1M")}/>
			<RadioBox label={getFNMLabels(61)} active={getStore("date_range_option") === "last3M"} updSelect={()=>updYU("last3M")}/>
			<RadioBox label={getFNMLabels(62)} active={getStore("date_range_option") === "last6M"} updSelect={()=>updYU("last6M")}/>
			<RadioBox label={getFNMLabels(63)} active={getStore("date_range_option") === "allYear"} updSelect={()=>updYU("allYear")}/>
			
			
			<RadioBox label={getFNMLabels(64)} active={getStore("date_range_option") === "range"} updSelect={()=>openCal("range")}/>

			

			<div className="_dsplFlx spaceAround" style={{marginTop:20}}>
				<div className="card"/>

			</div>
		</div>
	)

}



export default RangeDate;






