
import React, { useState, useEffect, useRef } from "react";

import "./styles.css"
import {  OpenModal } from "../../../components/DialogHRM";
import {  SvgIcon_Cmpt, SearchInput_Cmpt, LoadingColorSpinner_Cmpt } from "../../../components";
import { updStore, getStore, gen16CodeId, ObjectKeys,  parseFloatToDecimal, parseDateMMDDYYYY } from "../../../stores/Utils";

import { search_notary, getFNMLabels } from "../services/customer_fetch_service";
import ClientItem from "./customer_item";
import RangeDate from "./range_date";
import Categories2Filter from "./filter_categories";
import Provider2Filter from "./filter_Providers";
import { MovementAdd_Cmpt } from "..";
import { getall_categories } from "../../../features/FeedFromMobile/services/server_fetching";
import { useRefComputed } from "../../../hooks/useObjects";






const Svg = SvgIcon_Cmpt();


const SearchInput = SearchInput_Cmpt();


const LoadingColorSpinner = LoadingColorSpinner_Cmpt();

const MovementAdd = MovementAdd_Cmpt();





const CustomerView  = ({  }) => {
	const [, set_obs] = useState(1);
	

	
	const type = getStore("movement_type");
	

	const [range, set_Range] = useState(36);

	
	const loadingCompRef = useRef(null);
	const listDataRef = useRef(null);
	const filterBxRef = useRef(null);
	const filterIconBxRef = useRef(null);
	const filter = useRef(false);

	useEffect(() => {
		getall_categories(updObs);
		search_notary(callbackSearch);
		
	},[]);


	const drawBox=(e)=>{
		loadingCompRef?.current?.setAttribute("show",e);
		listDataRef?.current?.setAttribute("loading",e);
	}

	const drawFilterBox=(e)=>{
		filterBxRef?.current?.setAttribute("show",e);
		filterIconBxRef?.current?.setAttribute("active",e);
	}
  
	
	
	const loadingData = useRefComputed(false, drawBox );



	const updRange =  () => {
		set_Range(prev=>prev+36);
	}

	
	const updObs = () =>{
		set_obs(gen16CodeId());
	}

	

	const callbackSearch =  () => {
		setTimeout(()=>{
			loadingData.value = false;
			drawBox(false);
			if(range!==64){
				set_Range(64);
			}
			else{
				updObs();
			}
		},50);
	}

	const search_client = async (v) => {
		updStore("category_filter",v);
		if(!loadingData.value){
			loadingData.value = true;
		}
		drawBox(true);
		search_notary(callbackSearch);
	};

	const handleChange =  (v) => {
		if(!loadingData.value){
			loadingData.value = true;
		}
		drawBox(true);
	}

	const closeDetails = () =>{
		if(!loadingData.value){
			loadingData.value = true;
		}
		drawBox(true);
		search_notary(callbackSearch);
	}

	const openAddView =  () => {

		//updStore(qryKClient()+"_upd", clientItm);
		//updStore(qryKClient()+"_upd_bck", JSON.parse(JSON.stringify(clientItm)));

		let modal_data = {};
		modal_data["zIndex"] = 450;
		modal_data["height"] = "80vh";
		// data['observeResize']=true;
		modal_data["props"] = { minHeight: "1vh", overlay: true };
		modal_data["content"] =	<MovementAdd confirm={closeDetails} />
		OpenModal(modal_data);
	}

	const viewCustomers =  (v) => {
		let data = {};
		data["zIndex"] = 480;
		// data['observeResize']=true;
		data["props"] = { minHeight: "1vh", overlay: true };
		data["content"] = <Provider2Filter  confirm={search_client} />
		OpenModal(data);
	}

	const viewCategories =  (v) => {
		let data = {};
		data["zIndex"] = 480;
		// data['observeResize']=true;
		data["props"] = { minHeight: "1vh", overlay: true };
		data["content"] = <Categories2Filter type={type} confirm={search_client} init={getStore("category_filter")}/>
		OpenModal(data);
	}

	const openDateRange =  (v) => {
		let data = {};
		data["zIndex"] = 480;
		// data['observeResize']=true;
		data["props"] = { minHeight: "1vh", overlay: true };
		data["content"] = <RangeDate  confirm={search_client} />
		OpenModal(data);
	}
 
 

	let data2Render = getStore("client_list_"+type);

	const changeTab = (v) =>{
		updStore("movement_type",v);
		updObs();
		if(!loadingData.value){
			loadingData.value = true;
		}
		drawBox(true);
		search_notary(callbackSearch);
	}


	const changeFilter = () =>{
		filter.value = !filter.value;
		drawFilterBox(filter.value);
	}



	let lblColorType = getStore("movement_type") === "incomes"?"var(--primary-blue--backg-30)": "var(--primary-red--color-f7)";
	

	 
	let dateRangeString = getStore("date_range_comps")?.initDate ?parseDateMMDDYYYY(getStore("date_range_comps")?.initDate)  + " - " +parseDateMMDDYYYY(getStore("date_range_comps")?.lastDate) : null;
	let categoryFilterString = getStore("categories_ids")?.[getStore("category_filter")]?.name;
	let customerFilterString = getStore("providers_ids")?.[getStore("provider_filter")]?.name;



	return (
		<div 
			className="customer_bx_dash colorType mobile_version" 
		>
			<style>
				{`
					.colorType{
						--label-theme-color:${lblColorType};
					}
				`}
			</style>
			<div  className="colorType ">
				<div className="_dsplFlx " >
					<div style={{marginTop: "8px"}}>
						<SearchInput
							loadingColor={"var(-primary-blue--backg-30)"}
							placeholder={getFNMLabels(6)}
							obs={set_obs}
							fetchData={search_client}
							change={handleChange}
							callempty={search_client}
							keyFlds={"searchQryNotary"}
						/>
					</div>
					<div className="flexSpace"/>
					<div  className="icon blue30" >
						<div  className={` action `}  onClick={openAddView}>
							<Svg name={"add"}	/>
						</div>
					</div>
					<div className="flexSpace"/>
					<div  className="icon blue30">
						<div  className={` action `} ref={filterIconBxRef} onClick={changeFilter}>
							<Svg name={"filter"}	/>
						</div>
					</div>
					<div className="flexSpace"/>
				</div>
				<div className="_dsplFlx bx_filter" style={{marginTop:2}}>
					<div className="_dsplFlx w100 " >
						<div className={` _dsplFlx totalize `} >
							Total:
							<div className={`blue `} >
								${SumBalance(data2Render)}
							</div>
						</div>
						<div className="flexSpace"/>
						<div className={` tab_switch ${"expenses" === type?"red_orangered":"white_black"} `} onClick={()=>changeTab("expenses")} >
							{getFNMLabels(40)}
						</div>
						<div className="flexSpace"/>
						<div className={` tab_switch ${"incomes" === type?"blue_30":"white_black"} `}  onClick={()=>changeTab("incomes")}>
							{getFNMLabels(42)}
						</div>
						<div className="flexSpace"/>
					</div>
				</div>
				<div 
					className="_dsplFlx bx_filter_toogle" 
					style={{
						marginTop:2,
						}} 
					ref={filterBxRef}
				>
					<div className="_dsplFlx w100" >
						<div className="flexSpace"/>
						<div className={` btn_filter y2  ${dateRangeString?"w33 active":""} `} onClick={openDateRange} >
								{dateRangeString || getFNMLabels(55)}
						</div>
						<div className="flexSpace"/>
						<div className={` btn_filter y2  ${categoryFilterString?"w33 active":""} `} onClick={viewCategories}>
							{categoryFilterString || getFNMLabels(54) }
						</div>
						<div className="flexSpace"/>
						<div className={` btn_filter y2  ${customerFilterString?"w33 active":""} `} onClick={viewCustomers}>
							{customerFilterString || getFNMLabels(57)}
						</div>
						<div className="flexSpace"/>
					</div>
				</div>
				<>
					<div  className="loading_animation_container" style={{marginTop:2}} ref={loadingCompRef}>
						<div className="load_animation" style={{backgroundColor: getStore("movement_type") === "incomes"?"var(--primary-blue--backg-30)": "var(--primary-red--color-f7)"}}/>
						<div className="_dsplFlx "  style={{marginTop:32}}>
							<div className="flexSpace"/>
							<div className="icon_compr _dsplFlx" >
								<div className="lbl_saving">
										searching ... 
								</div>
								<LoadingColorSpinner stroke={getStore("movement_type") === "incomes"?"var(--primary-blue--backg-30)": "var(--primary-red--color-f7)"} size={24} strokeW={8}/>
							</div>
							<div className="flexSpace"/>
						</div>
					</div>
				
					<div className="clients_container"  ref={listDataRef}>
						{data2Render && data2Render?.map((cid, ind43)=>{
							return (
								<ClientItem
									data={cid} 
									elmId={cid.movementId} 
									key={cid.movementId+"mov_id"}
									type={type}
									range2Scroll={range-ind43===24}
									show={ind43 < range}
									updRange={updRange}
								/>
							)
						})}
					</div>
				</>
			</div>
		</div>
	)

}

export default CustomerView;



const SumBalance = (obj) => {
	let balance = 0;
	obj && ObjectKeys(obj)?.map((flds, indE)=>{
		let amount = (obj[flds].amount*1);
		balance =  parseFloatToDecimal(balance,2)*1 + parseFloatToDecimal(amount,2)*1;
	});
	return  parseFloatToDecimal(balance,2)*1;
}  





